<?php
declare(strict_types=1);
define('HWC_SKIP_GLOBAL_SHELL',true);
require_once __DIR__.'/config/dynamic_forms.php';
$pdo=role_portal_db();dynamic_forms_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);if(!$user||!in_array((string)$user['role_code'],['admin','coach'],true)){header('Location: ../login.php');exit;}$isAdmin=(string)$user['role_code']==='admin';$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();$error=null;$success=null;
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){if(!$isAdmin)throw new RuntimeException('Only Administrator can change form design.');security_step17_verify_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');
  if($action==='save_form'){$id=(int)($_POST['form_id']??0);$key=preg_replace('/[^a-z0-9_]+/','_',strtolower(trim((string)($_POST['form_key']??''))));$name=trim((string)($_POST['form_name']??''));$page=basename(trim((string)($_POST['target_page']??'')));if($key===''||$name===''||$page==='')throw new RuntimeException('Form key, name and target page are required.');if($id){$s=$pdo->prepare("UPDATE dynamic_form_definitions SET form_key=?,form_name=?,target_page=?,description=?,sort_order=?,updated_by=? WHERE id=? AND organization_id=?");$s->execute([$key,$name,$page,trim((string)($_POST['description']??'')),(int)($_POST['sort_order']??100),(int)$user['id'],$id,$orgId]);}else{$s=$pdo->prepare("INSERT INTO dynamic_form_definitions(organization_id,form_key,form_name,target_page,description,sort_order,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$orgId,$key,$name,$page,trim((string)($_POST['description']??'')),(int)($_POST['sort_order']??100),(int)$user['id'],(int)$user['id']]);}$success='Form saved.';}
  elseif($action==='save_field'){$formId=(int)($_POST['form_id']??0);$fieldId=(int)($_POST['field_id']??0);$key=trim((string)($_POST['field_key']??''));$label=trim((string)($_POST['field_label']??''));$type=in_array((string)($_POST['field_type']??''),['select','radio','checkbox','text'],true)?(string)$_POST['field_type']:'select';if($formId<=0||$key===''||$label==='')throw new RuntimeException('Form, field name and label are required.');$parent=(int)($_POST['parent_field_id']??0)?:null;if($fieldId){$s=$pdo->prepare("UPDATE dynamic_form_fields SET field_key=?,field_label=?,field_type=?,help_text=?,parent_field_id=?,is_required=?,sort_order=?,status=? WHERE id=? AND organization_id=?");$s->execute([$key,$label,$type,trim((string)($_POST['help_text']??'')),$parent,isset($_POST['is_required'])?1:0,(int)($_POST['sort_order']??100),(string)($_POST['status']??'active'),$fieldId,$orgId]);}else{$s=$pdo->prepare("INSERT INTO dynamic_form_fields(organization_id,form_id,field_key,field_label,field_type,help_text,parent_field_id,is_required,sort_order,status) VALUES(?,?,?,?,?,?,?,?,?,'active')");$s->execute([$orgId,$formId,$key,$label,$type,trim((string)($_POST['help_text']??'')),$parent,isset($_POST['is_required'])?1:0,(int)($_POST['sort_order']??100)]);}$success='Field mapping saved.';}
  elseif($action==='save_option'){$fieldId=(int)($_POST['field_id']??0);$optionId=(int)($_POST['option_id']??0);$value=trim((string)($_POST['option_value']??''));$label=trim((string)($_POST['option_label']??''));if($fieldId<=0||$value===''||$label==='')throw new RuntimeException('Field, option value and label are required.');$parent=trim((string)($_POST['parent_option_value']??''))?:null;if($optionId){$s=$pdo->prepare("UPDATE dynamic_form_options SET option_value=?,option_label=?,parent_option_value=?,sort_order=?,status=? WHERE id=? AND organization_id=?");$s->execute([$value,$label,$parent,(int)($_POST['sort_order']??100),(string)($_POST['status']??'active'),$optionId,$orgId]);}else{$s=$pdo->prepare("INSERT INTO dynamic_form_options(organization_id,field_id,option_value,option_label,parent_option_value,sort_order,status) VALUES(?,?,?,?,?,?,'active')");$s->execute([$orgId,$fieldId,$value,$label,$parent,(int)($_POST['sort_order']??100)]);}$success='Option saved and is ready for its mapped form.';}
  security_step17_audit($pdo,(int)$user['id'],'dynamic_form_designer_updated','dynamic_form',null,['action'=>$action]);
 }
}catch(Throwable $e){$error=$e->getMessage();}
$forms=dynamic_forms_catalog($pdo,$orgId);$selectedKey=trim((string)($_GET['form']??$_POST['selected_form']??($forms[0]['form_key']??'')));$selected=null;foreach($forms as $f)if((string)$f['form_key']===$selectedKey)$selected=$f;if(!$selected&&$forms)$selected=$forms[0];$fields=[];$options=[];if($selected){$s=$pdo->prepare("SELECT * FROM dynamic_form_fields WHERE organization_id=? AND form_id=? ORDER BY sort_order,id");$s->execute([$orgId,(int)$selected['id']]);$fields=$s->fetchAll();if($fields){$ids=array_column($fields,'id');$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM dynamic_form_options WHERE organization_id=? AND field_id IN ($marks) ORDER BY field_id,sort_order,id");$s->execute([$orgId,...$ids]);$options=$s->fetchAll();}}
$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Smart Form Designer</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f8fd;color:#253a30;font-family:Inter,Segoe UI,Arial,sans-serif}.fd-head{position:sticky;top:0;z-index:5;padding:16px 18px;background:linear-gradient(135deg,#fff,#eff7ff);border-bottom:1px solid #dfe7e2}.fd-head h1{margin:0;font-size:1.25rem}.fd-head p{margin:4px 0 0;color:#6d7b74;font-size:.76rem}.fd-tabs{display:flex;gap:7px;overflow:auto;padding:12px 16px}.fd-tabs a{white-space:nowrap;padding:8px 11px;border:1px solid #dbe4df;border-radius:10px;background:#fff;color:#3e5148;text-decoration:none;font-size:.7rem;font-weight:800}.fd-tabs a.active{background:#5946dc;color:#fff}.fd-main{padding:0 16px 24px}.fd-card{margin-bottom:12px;padding:15px;border:1px solid #dce6e0;border-radius:16px;background:#fff;box-shadow:0 8px 24px rgba(43,65,52,.05)}.fd-card h2{margin:0 0 4px;font-size:1rem}.fd-card>p{margin:0 0 12px;color:#718078;font-size:.7rem}.fd-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.fd-grid label{display:grid;gap:4px;color:#586b61;font-size:.65rem;font-weight:800}.fd-grid .wide{grid-column:1/-1}input,select,textarea{width:100%;padding:9px 10px;border:1px solid #d9e3dd;border-radius:9px;background:#fbfdfc;color:#293c33}button{padding:9px 12px;border:0;border-radius:9px;background:#247649;color:#fff;font-weight:850;cursor:pointer}.fd-row{display:grid;grid-template-columns:1fr 1.2fr 1fr .7fr auto;gap:8px;align-items:end;padding:9px 0;border-top:1px solid #edf0ee}.fd-row small{display:block;color:#75837c}.fd-note{padding:10px;border-radius:10px;background:#fff8e8;color:#735b24;font-size:.7rem}.ok,.bad{margin:10px 16px;padding:10px;border-radius:10px;font-size:.74rem}.ok{background:#e9f8ef;color:#176d43}.bad{background:#fff0f0;color:#a13a3a}@media(max-width:700px){.fd-grid,.fd-row{grid-template-columns:1fr}.fd-grid .wide{grid-column:auto}}</style></head><body><header class="fd-head"><h1>Smart Form Designer</h1><p><?=$isAdmin?'Edit fields, options and parent-child relationships.':'Coach preview • Administrator controls global form design.'?></p></header><?php if($success):?><div class="ok"><?=$h($success)?></div><?php endif?><?php if($error):?><div class="bad"><?=$h($error)?></div><?php endif?><nav class="fd-tabs"><?php foreach($forms as $f):?><a class="<?=($selected&&$f['id']===$selected['id'])?'active':''?>" href="?form=<?=$h($f['form_key'])?>"><?=$h($f['form_name'])?></a><?php endforeach?></nav><main class="fd-main"><?php if($selected):?><section class="fd-card"><h2><?=$h($selected['form_name'])?></h2><p><?=$h($selected['description'])?> • Target: <?=$h($selected['target_page'])?></p><div class="fd-note">Field Name must match the existing HTML form field name. Dependent options use the parent field’s saved option value.</div></section><?php if($isAdmin):?><section class="fd-card"><h2>Add field mapping</h2><p>Create a configurable field or connect an existing dropdown.</p><form method="post" class="fd-grid"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><input type="hidden" name="action" value="save_field"><input type="hidden" name="form_id" value="<?=(int)$selected['id']?>"><input type="hidden" name="selected_form" value="<?=$h($selected['form_key'])?>"><label>Field Name<input name="field_key" placeholder="order_type" required></label><label>Display Label<input name="field_label" required></label><label>Field Type<select name="field_type"><option value="select">Dropdown</option><option value="radio">Radio options</option><option value="checkbox">Checkbox options</option><option value="text">Text field</option></select></label><label>Depends On<select name="parent_field_id"><option value="">Independent</option><?php foreach($fields as $field):?><option value="<?=(int)$field['id']?>"><?=$h($field['field_label'])?></option><?php endforeach?></select></label><label class="wide">Help Text<input name="help_text"></label><label>Order<input type="number" name="sort_order" value="100"></label><label><span>Required</span><input type="checkbox" name="is_required" value="1"></label><div><button type="submit">Add Field</button></div></form></section><?php endif?><section class="fd-card"><h2>Fields &amp; Options</h2><p><?=count($fields)?> mapped fields • <?=count($options)?> saved options</p><?php foreach($fields as $field):?><article class="fd-card"><h2><?=$h($field['field_label'])?></h2><p>Name: <b><?=$h($field['field_key'])?></b> • <?=$h($field['field_type'])?><?=$field['parent_field_id']?' • dependent':''?></p><?php foreach($options as $option):if((int)$option['field_id']!==(int)$field['id'])continue;?><div class="fd-row"><b><?=$h($option['option_label'])?><small><?=$h($option['option_value'])?></small></b><span>Parent: <?=$h($option['parent_option_value']?:'Any')?></span><span><?=$h($option['status'])?></span><span>#<?=(int)$option['sort_order']?></span><?php if($isAdmin):?><form method="post"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><input type="hidden" name="action" value="save_option"><input type="hidden" name="field_id" value="<?=(int)$field['id']?>"><input type="hidden" name="option_id" value="<?=(int)$option['id']?>"><input type="hidden" name="option_value" value="<?=$h($option['option_value'])?>"><input type="hidden" name="option_label" value="<?=$h($option['option_label'])?>"><input type="hidden" name="parent_option_value" value="<?=$h($option['parent_option_value'])?>"><input type="hidden" name="sort_order" value="<?=(int)$option['sort_order']?>"><input type="hidden" name="status" value="<?=$option['status']==='active'?'hidden':'active'?>"><button type="submit"><?=$option['status']==='active'?'Hide':'Activate'?></button></form><?php endif?></div><?php endforeach?><?php if($isAdmin):?><form method="post" class="fd-grid"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><input type="hidden" name="action" value="save_option"><input type="hidden" name="field_id" value="<?=(int)$field['id']?>"><label>New Option Label<input name="option_label" required></label><label>Saved Value<input name="option_value" required></label><label>Parent Option Value<input name="parent_option_value" placeholder="Blank = always visible"></label><label>Order<input type="number" name="sort_order" value="100"></label><div><button type="submit">Add Option</button></div></form><?php endif?></article><?php endforeach?></section><?php endif?></main></body></html>
